"use strict";(globalThis.webpackChunkdocusaurus_template_openapi_docs=globalThis.webpackChunkdocusaurus_template_openapi_docs||[]).push([[4723],{7001(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>i,default:()=>d,frontMatter:()=>s,metadata:()=>r,toc:()=>c});var r=n(94080),a=n(74848),o=n(28453);const s={slug:"consistent-agentic-api-layer",title:"Every Protocol. Every Framework. Zero Code Changes.",authors:["leseb"],tags:["agentic","multi-sdk","sovereignty","architecture"],date:new Date("2026-05-11T00:00:00.000Z")},i=void 0,l={authorsImageUrls:[void 0]},c=[{value:"The problem: protocol fragmentation",id:"the-problem-protocol-fragmentation",level:2},{value:"OGX as the translation layer",id:"ogx-as-the-translation-layer",level:2},{value:"More than a proxy",id:"more-than-a-proxy",level:2},{value:"What sovereignty actually means",id:"what-sovereignty-actually-means",level:2},{value:"Framework-agnostic by design",id:"framework-agnostic-by-design",level:2},{value:"Where this is heading",id:"where-this-is-heading",level:2}];function h(e){const t={a:"a",code:"code",em:"em",h2:"h2",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"Agents shouldn't change a line of code to run on your infrastructure."}),"\n",(0,a.jsx)(t.p,{children:"That sentence sounds simple, but it represents a fundamental shift in how enterprises can adopt AI agents. Today, every agentic framework speaks a different protocol. Teams using Claude Agents talk Anthropic Messages. Teams using ADK talk Google Interactions. Most agents still call OpenAI Chat Completions or the newer Responses API. Each choice creates a hard dependency on a vendor's infrastructure, SDK, and API contract."}),"\n",(0,a.jsx)(t.p,{children:"OGX exists to break that coupling. It's a server that speaks every major agentic protocol natively, translating them to any model running on any infrastructure. No vendor lock-in. No SDK rewrites."}),"\n",(0,a.jsx)(t.h2,{id:"the-problem-protocol-fragmentation",children:"The problem: protocol fragmentation"}),"\n",(0,a.jsx)(t.p,{children:"Enterprise AI adoption doesn't happen in a vacuum. Different teams pick different frameworks based on their use case, their experience, and their model preference. One team builds with Claude Code. Another ships with OpenAI's Responses API. A third experiments with Google's ADK. Each choice is reasonable in isolation."}),"\n",(0,a.jsx)(t.p,{children:"But at the platform level, this creates a mess. Every protocol means a different API contract. Every API contract means a different deployment path, a different set of credentials, a different operational surface. The platform team ends up managing $N$ distinct integration points instead of one."}),"\n",(0,a.jsx)(t.p,{children:"Worse, the choice of SDK becomes coupled to the choice of model and infrastructure. Want to use the Anthropic SDK with an open-weight model running on-prem? Want to use the OpenAI SDK against a model served by vLLM? Want to switch providers without rewriting your application? In the current landscape, each of those requires work."}),"\n",(0,a.jsx)(t.p,{children:"This is the fragmentation tax. It slows adoption, increases operational burden, and creates vendor lock-in at the API layer \u2014 even when the models themselves are open."}),"\n",(0,a.jsx)(t.h2,{id:"ogx-as-the-translation-layer",children:"OGX as the translation layer"}),"\n",(0,a.jsx)(t.p,{children:"OGX solves this by implementing three API surfaces natively on a single server:"}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"OpenAI API"})," \u2014 Chat Completions, Responses, Embeddings, and the full suite of supporting endpoints. This is the baseline most agents and frameworks already use."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Anthropic Messages API"})," \u2014 the multi-turn conversation protocol that Claude Agents and Claude Code speak natively."]}),"\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Google Interactions API"})," \u2014 the emerging agentic protocol from the ADK and Gemini ecosystem."]}),"\n",(0,a.jsx)(t.p,{children:"All three share the same underlying inference providers. A single OGX deployment can serve clients using different SDKs simultaneously, against the same models:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-python",children:'from openai import OpenAI\n\nopenai_client = OpenAI(base_url="http://ogx-server:8321/v1", api_key="key")\n\nfrom anthropic import Anthropic\n\nanthropic_client = Anthropic(base_url="http://ogx-server:8321/v1", api_key="key")\n\nfrom google import genai\nfrom google.genai import types\n\ngoogle_client = genai.Client(\n    api_key="key",\n    http_options=types.HttpOptions(\n        base_url="http://ogx-server:8321",\n        api_version="v1alpha",\n    ),\n)\n'})}),"\n",(0,a.jsx)(t.p,{children:"Three SDKs. One server. Same model. No translation code in your application."}),"\n",(0,a.jsx)(t.h2,{id:"more-than-a-proxy",children:"More than a proxy"}),"\n",(0,a.jsxs)(t.p,{children:["OGX isn't just routing requests to different backends. That would be a reverse proxy, and those already exist. What makes OGX different is that it runs a ",(0,a.jsx)(t.strong,{children:"server-side agentic loop"})," \u2014 inference, tool calling, RAG, MCP integration, conversation state management \u2014 on supported API surfaces, with feature parity continuing to expand across protocols."]}),"\n",(0,a.jsxs)(t.p,{children:["When a client sends a request through the Responses API with ",(0,a.jsx)(t.code,{children:"file_search"})," and MCP tools attached, the server handles the entire orchestration: searching vector stores, calling MCP servers, chaining tool results back into the model, and synthesizing a final answer. Your client gets a response. It doesn't manage a loop."]}),"\n",(0,a.jsxs)(t.p,{children:["This is the difference between a proxy and an application server. A proxy translates formats. OGX translates formats ",(0,a.jsx)(t.em,{children:"and"})," runs the agentic logic that makes those formats useful."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-python",children:'from openai import OpenAI\n\nclient = OpenAI(base_url="http://ogx-server:8321/v1", api_key="key")\n\nresponse = client.responses.create(\n    model="llama-3.3-70b",\n    input="Summarize the Q1 compliance updates and check if any affect our deployment timeline.",\n    tools=[\n        {"type": "file_search", "vector_store_ids": ["vs_compliance"]},\n        {\n            "type": "mcp",\n            "server_label": "project-tracker",\n            "server_url": "http://internal-api:8000/sse",\n        },\n    ],\n)\n'})}),"\n",(0,a.jsx)(t.p,{children:"One API call. Multiple tools. Multi-step reasoning. All server-side."}),"\n",(0,a.jsx)(t.h2,{id:"what-sovereignty-actually-means",children:"What sovereignty actually means"}),"\n",(0,a.jsx)(t.p,{children:"The conversation around AI sovereignty usually focuses on model weights. Can we run the model on our own hardware? Can we fine-tune it? Do we control the training data? These are important questions, and open-weight models answer them."}),"\n",(0,a.jsx)(t.p,{children:"But sovereignty at the model layer isn't enough. If your application is written against a proprietary API, you're still locked in \u2014 just at a different layer. Switching from one provider to another means rewriting your agent code, re-testing your tool integrations, and re-validating your orchestration logic."}),"\n",(0,a.jsx)(t.p,{children:"OGX extends sovereignty to the API contract. Your application talks to OGX using whatever SDK your team prefers. OGX talks to whatever inference provider you've deployed. The two decisions are independent:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Use the Anthropic SDK with Ollama running on-prem"}),"\n",(0,a.jsx)(t.li,{children:"Use the OpenAI SDK with vLLM on your Kubernetes cluster"}),"\n",(0,a.jsx)(t.li,{children:"Use the Google SDK with Bedrock in AWS"}),"\n",(0,a.jsx)(t.li,{children:"Switch any of these without touching application code"}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"And once the platform owns the API contract, it can enforce policy at the protocol layer. Attribute-based access control determines which models, tools, or APIs a given team or user can reach \u2014 regardless of which SDK they're calling through. A data science team gets access to large reasoning models and file search. An internal chatbot gets a smaller model and no tool access. The controls live in the platform, not scattered across framework configs."}),"\n",(0,a.jsx)(t.p,{children:"This is something you can't do when each framework talks directly to its own provider. Centralized policy enforcement is a natural consequence of centralized API translation."}),"\n",(0,a.jsx)(t.p,{children:"The customer owns the API contract, not just the model weights. That's what sovereignty means at the platform level."}),"\n",(0,a.jsx)(t.h2,{id:"framework-agnostic-by-design",children:"Framework-agnostic by design"}),"\n",(0,a.jsx)(t.p,{children:"The protocol diversity in the agentic ecosystem isn't going away. Claude Code, Codex, ADK, Strands, LangGraph, OpenClaw \u2014 each framework has its own strengths and its own protocol preferences. Telling teams to standardize on one framework is unrealistic and counterproductive."}),"\n",(0,a.jsx)(t.p,{children:"OGX takes a different approach: let teams choose whatever framework fits their use case, and make the platform handle the protocol differences. A team building with Claude Code doesn't need to know or care that the platform is running open-weight models on OpenShift. A team using ADK doesn't need to rewrite their agents if the organization decides to switch inference providers."}),"\n",(0,a.jsx)(t.p,{children:'This is what "zero code changes" means in practice. Not zero effort to set up the platform \u2014 that takes real engineering. But zero changes to the agent code that teams have already built and tested.'}),"\n",(0,a.jsx)(t.h2,{id:"where-this-is-heading",children:"Where this is heading"}),"\n",(0,a.jsx)(t.p,{children:"OGX already supports the core API surfaces. The work ahead is deepening that support:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Richer tool orchestration"})," across all three protocols \u2014 parallel tool calls, code interpretation, and response branching"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Full agentic feature parity"})," \u2014 making sure every protocol surface gets the same server-side capabilities, not just basic inference"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Production hardening"})," \u2014 storage persistence, multi-provider auth, telemetry, and upgrade paths that enterprise deployments require"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"The goal is straightforward: any agent, any framework, any model, any infrastructure. One server."}),"\n",(0,a.jsxs)(t.p,{children:["If your team is building agents and doesn't want to bet on a single vendor's API contract, ",(0,a.jsx)(t.a,{href:"https://ogx-ai.github.io/docs",children:"get started with OGX"})," or join the conversation on ",(0,a.jsx)(t.a,{href:"https://discord.gg/bUYRqEvK6",children:"Discord"}),"."]})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>i});var r=n(96540);const a={},o=r.createContext(a);function s(e){const t=r.useContext(o);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),r.createElement(o.Provider,{value:t},e.children)}},94080(e){e.exports=JSON.parse('{"permalink":"/v1.2.2/blog/consistent-agentic-api-layer","source":"@site/blog/2026-05-11-consistent-agentic-api-layer.md","title":"Every Protocol. Every Framework. Zero Code Changes.","description":"Agents shouldn\'t change a line of code to run on your infrastructure.","date":"2026-05-11T00:00:00.000Z","tags":[{"inline":true,"label":"agentic","permalink":"/v1.2.2/blog/tags/agentic"},{"inline":true,"label":"multi-sdk","permalink":"/v1.2.2/blog/tags/multi-sdk"},{"inline":true,"label":"sovereignty","permalink":"/v1.2.2/blog/tags/sovereignty"},{"inline":true,"label":"architecture","permalink":"/v1.2.2/blog/tags/architecture"}],"readingTime":3.92,"hasTruncateMarker":true,"authors":[{"name":"S\xe9bastien Han","title":"OGX Core Team","url":"https://github.com/leseb","imageURL":"https://github.com/leseb.png","key":"leseb","page":null}],"frontMatter":{"slug":"consistent-agentic-api-layer","title":"Every Protocol. Every Framework. Zero Code Changes.","authors":["leseb"],"tags":["agentic","multi-sdk","sovereignty","architecture"],"date":"2026-05-11T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"OGX 1.0: The Open Agentic API Server is Production-Ready","permalink":"/v1.2.2/blog/ogx-v1"},"nextItem":{"title":"OGX \u2764\ufe0f OpenCode","permalink":"/v1.2.2/blog/opencode-blog"}}')}}]);